{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
{\*\listtable{\list\listtemplateid1{\listlevel\levelnfc0\levelnfcn0\leveljc0\leveljcn0\levelfollow0\levelstartat1\levelindent0{\leveltext\'01\u8226 ?;}{\levelnumbers;}\fi-360\li360\lin360 }{\listname ;}\listid1}
{\list\listtemplateid2{\listlevel\levelnfc23\levelnfcn23\leveljc0\leveljcn0\levelfollow0\levelstartat1\levelindent0{\leveltext\'01\u8226 ?;}{\levelnumbers;}\fi-360\li360\lin360 }{\listname ;}\listid2}
{\list\listtemplateid3{\listlevel\levelnfc23\levelnfcn23\leveljc0\leveljcn0\levelfollow0\levelstartat1\levelindent0{\leveltext\'01\u8226 ?;}{\levelnumbers;}\fi-360\li360\lin360 }{\listname ;}\listid3}
}
{\*\listoverridetable{\listoverride\listid1\listoverridecount0\ls1}{\listoverride\listid2\listoverridecount0\ls2}{\listoverride\listid3\listoverridecount0\ls3}}
\widowctrl\hyphauto

{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel0 \b \fs34 ZP Suite\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 A free, open-source toolkit for voiceover, dubbing, podcasts, e-learning and broadcast workflows in REAPER. It brings script reading, subtitle handling, project preparation, accessible controls and ZP audio tools into one REAPER setup.\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 {\b Prefer Italian?} See {\field{\*\fldinst{HYPERLINK "README.it.md"}}{\fldrslt{\ul
README in Italian
}}}
. The Suite itself is available in Italian and English.\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Choose your language\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 After installing or updating, open {\b 33 Welcome} from REAPER's Action List. Under {\b Suite language}, choose {\b English} or {\b Italiano}. This preference is saved and is independent of REAPER's own language. The {\f1 \fs24 ?} help buttons open the guide in the selected Suite language.\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Install with ReaPack\par}
{\pard \ql \f0 \fs24 \sa180 \li360 \fi-360\ls1\ilvl0\tx360 {\listtext\tab 1.\tab} In REAPER, choose {\b Extensions \u8594 ? ReaPack \u8594 ? Import repositories}.\par}
{\pard \ql \f0 \fs24 \sa180 \li360 \fi-360\ls1\ilvl0\tx360 {\listtext\tab 2.\tab} Add this repository URL:\par}
{\pard \ql \f0 \fs24 \sa180 \li360 \ls1\ilvl0\fi0 {\f1 \fs24 https://github.com/capitanpaolone/zp-suite/raw/master/index.xml}\par}
{\pard \ql \f0 \fs24 \sa180 \li360 \fi-360\ls1\ilvl0\tx360 {\listtext\tab 3.\tab} Choose {\b Extensions \u8594 ? ReaPack \u8594 ? Browse packages}, search for {\b ZP}, and install {\b ZP Studio Suite} and any ZP effects you need.\par}
{\pard \ql \f0 \fs24 \sa180 \li360 \fi-360\ls1\ilvl0\tx360 {\listtext\tab 4.\tab} Synchronize packages to receive updates.\sa180\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 The Suite works in a clean REAPER install. SWS, js_ReaScriptAPI and OSARA are optional; they add features where available.\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 What is included\par}
{\pard \ql \f0 \fs24 \sa0 \li360 \fi-360\ls2\ilvl0\tx360 {\listtext\tab \bullet \tab} {\b ZP Studio Suite} \u8212- teleprompters, SRT import/export and references, project tools, mixdown preparation, voice-minute reports, Voice Cleaner and accessible workflows.\par}
{\pard \ql \f0 \fs24 \sa0 \li360 \fi-360\ls2\ilvl0\tx360 {\listtext\tab \bullet \tab} {\b ZP Voce} \u8212- voice chains, dialogue tools and voice/music processing.\par}
{\pard \ql \f0 \fs24 \sa0 \li360 \fi-360\ls2\ilvl0\tx360 {\listtext\tab \bullet \tab} {\b ZP Master} \u8212- mastering and reference-tone tools.\par}
{\pard \ql \f0 \fs24 \sa0 \li360 \fi-360\ls2\ilvl0\tx360 {\listtext\tab \bullet \tab} {\b ZP Misura} \u8212- loudness meters, oscilloscope and passive signal probes.\sa180\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Not included in this version\par}
{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 ZP Montaggio Parlato (prototype), ZP BrownSlope Dynamic Guard, ZP BrownSlope Prism and ZP Speech Engine are still in development and are not part of this ReaPack release.\par}
